import { S3Client, ListObjectsV2Command, GetObjectCommand } from '@aws-sdk/client-s3';
import { PrivateAPIUsageController } from './usage.controller.js';

const s3 = new S3Client({ region: 'us-east-1' });
const BUCKET = process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME;

const list = async (prefix: string) => {
    const r = await s3.send(new ListObjectsV2Command({ Bucket: BUCKET, Prefix: prefix }));
    return r.Contents || [];
};
const get = async (key: string) => {
    const r = await s3.send(new GetObjectCommand({ Bucket: BUCKET, Key: key }));
    return JSON.parse(await r.Body.transformToString());
};

const makeController = () =>
    new PrivateAPIUsageController({ create: jest.fn() } as any, {} as any, {} as any);

describe('datastore usage DLQ', () => {
    it('writes bad json under the source file', async () => {
        const controller = makeController();
        const s3Key = `biz-test/2026/03/01/badjson-${Date.now()}.json`;
        const message = '{"customerId":"cus_a","dimensi';
        await expect(controller.dbUsage({ message, s3Key })).rejects.toThrow(/Invalid message format/);
        const objs = await list(s3Key);
        expect(objs.length).toBe(1);
        expect(objs[0].Key).toMatch(new RegExp(`^${s3Key}-[a-z0-9]{6}\\.json$`));
        const doc = await get(objs[0].Key);
        console.log(JSON.stringify(doc));
        expect(doc.failedDocument).toEqual({ originalFileContent: message, s3Key });
        expect(doc.metadata.results).toBe('failed to load data');
        expect(doc.metadata.orginalProcessedName).toBe(s3Key);
        expect(doc.metadata.errorInfo.name).toBe('SyntaxError');
        expect(doc.metadata.errorInfo.stack).toBeUndefined();
        expect(typeof doc.metadata.timestamp).toBe('string');
    });

    it('writes validation failures and does not overwrite prior failures', async () => {
        const controller = makeController();
        const s3Key = `biz-test/2026/03/01/invalid-${Date.now()}.json`;
        const message = JSON.stringify({ timestamp: 'nope', customerId: 'c', dimensionId: 'd', recordValue: 'x' });
        await expect(controller.dbUsage({ message, s3Key })).rejects.toThrow();
        await expect(controller.dbUsage({ message, s3Key })).rejects.toThrow();
        const objs = await list(s3Key);
        expect(objs.length).toBe(2);
        const doc = await get(objs[0].Key);
        console.log(JSON.stringify(doc));
        expect(Array.isArray(doc.metadata.errorInfo)).toBe(true);
    });

    it('retains messages with no source file', async () => {
        const controller = makeController();
        const before = await list('meteringco-unknown/');
        await expect(controller.dbUsage({ message: '{"a":1}' })).rejects.toThrow();
        const after = await list('meteringco-unknown/');
        expect(after.length).toBe(before.length + 1);
        const newKey = after.map((o) => o.Key).filter((k) => !before.map((o) => o.Key).includes(k))[0];
        const doc = await get(newKey);
        console.log(newKey, JSON.stringify(doc));
        expect(doc.failedDocument.originalFileContent).toBe('{"a":1}');
        expect(doc.metadata.orginalProcessedName).toMatch(/^meteringco-unknown\//);
        expect(newKey.startsWith(doc.metadata.orginalProcessedName)).toBe(true);
    });

    it('still rejects when the dlq write fails', async () => {
        const controller = makeController();
        const original = process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME;
        process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME = 'bucket-that-does-not-exist-xyz';
        try {
            await expect(controller.dbUsage({ message: 'nope', s3Key: 'biz-test/x.json' })).rejects.toThrow(
                /Invalid message format/,
            );
        } finally {
            process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME = original;
        }
        delete process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME;
        await expect(controller.dbUsage({ message: 'nope', s3Key: 'biz-test/x.json' })).rejects.toThrow(
            /Invalid message format/,
        );
        process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME = BUCKET;
    });

    it('does not dlq successful messages', async () => {
        const controller = makeController();
        const s3Key = `biz-test/2026/03/01/good-${Date.now()}.json`;
        const message = JSON.stringify({
            timestamp: new Date().toISOString(),
            customerId: 'cus_a',
            dimensionId: 'dim-a',
            recordValue: '5',
        });
        await controller.dbUsage({ message, s3Key });
        expect((await list(s3Key)).length).toBe(0);
    });
});
